//
//  KeychainHelper.swift
//  SwiftMandarin
//
//  Lightweight, cross-platform (iOS/macOS) Keychain wrapper for storing
//  sensitive secrets such as cloud AI provider API keys. Uses a generic
//  password item keyed by an `account` string. Never stores secrets in
//  UserDefaults.
//

import Foundation
import Security

/// Secure storage for small secrets (API keys) backed by the system Keychain.
enum KeychainHelper {

    /// Service namespace for all SwiftMandarin secrets.
    private static let service = "linroger022.SwiftMandarin.secrets"

    /// Store (or update) a secret for the given account.
    /// Passing an empty/whitespace string deletes any existing item.
    /// - Returns: `true` on success.
    @discardableResult
    static func set(_ value: String, account: String) -> Bool {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)

        // Always remove any existing item first so we can cleanly insert.
        _ = delete(account: account)

        // Empty value means "clear the key".
        guard !trimmed.isEmpty else { return true }
        guard let data = trimmed.data(using: .utf8) else { return false }

        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecValueData as String: data,
            kSecAttrAccessible as String: kSecAttrAccessibleAfterFirstUnlock,
        ]
        return SecItemAdd(query as CFDictionary, nil) == errSecSuccess
    }

    /// Retrieve the secret for the given account, or `nil` if not present.
    static func get(account: String) -> String? {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
            kSecReturnData as String: true,
            kSecMatchLimit as String: kSecMatchLimitOne,
        ]

        var result: AnyObject?
        let status = SecItemCopyMatching(query as CFDictionary, &result)
        guard status == errSecSuccess,
              let data = result as? Data,
              let string = String(data: data, encoding: .utf8) else {
            return nil
        }
        return string
    }

    /// Delete the secret for the given account.
    @discardableResult
    static func delete(account: String) -> Bool {
        let query: [String: Any] = [
            kSecClass as String: kSecClassGenericPassword,
            kSecAttrService as String: service,
            kSecAttrAccount as String: account,
        ]
        let status = SecItemDelete(query as CFDictionary)
        return status == errSecSuccess || status == errSecItemNotFound
    }

    /// Whether a non-empty secret exists for the given account.
    static func has(account: String) -> Bool {
        guard let value = get(account: account) else { return false }
        return !value.isEmpty
    }
}

//
//  AppPreferences.swift
//  SwiftMandarin
//
//  App-wide, cross-cutting user preferences that make the app bilingual:
//  - LearnerMode flips the app between English-centric and Mandarin-centric.
//  - PhotoScanLanguage controls OCR recognition language (fixes the
//    "stuck on English / can't read Mandarin" photo bug).
//  - dualNarration enables speaking both the word and its translation.
//

import Foundation
import SwiftUI

// MARK: - Learner Mode

/// Who the app is centered on. Drives default translation direction,
/// default OCR scan language, and which language is emphasized in narration.
enum LearnerMode: String, CaseIterable, Identifiable, Codable {
    /// English speaker learning Mandarin (the original app audience).
    case englishToMandarin
    /// Mandarin speaker learning English.
    case mandarinToEnglish
    /// Learning both languages at once.
    case bilingual

    var id: String { rawValue }

    /// Short label shown in the user's own language emphasis.
    var displayName: String {
        switch self {
        case .englishToMandarin: return "English speaker learning 中文"
        case .mandarinToEnglish: return "中文母语者学英语"
        case .bilingual: return "Bilingual · 双语学习"
        }
    }

    var shortLabel: String {
        switch self {
        case .englishToMandarin: return "EN → 中"
        case .mandarinToEnglish: return "中 → EN"
        case .bilingual: return "EN ⇄ 中"
        }
    }

    var iconName: String {
        switch self {
        case .englishToMandarin: return "character.book.closed"
        case .mandarinToEnglish: return "a.book.closed"
        case .bilingual: return "arrow.left.arrow.right.circle"
        }
    }

    var detail: String {
        switch self {
        case .englishToMandarin:
            return "Interface and defaults favor translating into Chinese; narration leads with Mandarin."
        case .mandarinToEnglish:
            return "界面与默认方向偏向译成英文；朗读以英文为主。"
        case .bilingual:
            return "Balanced defaults for studying both languages; both narrations are always offered."
        }
    }

    /// The default translation direction this mode implies.
    var defaultDirection: TranslationDirection {
        switch self {
        case .englishToMandarin, .bilingual: return .englishToChinese
        case .mandarinToEnglish: return .chineseToEnglish
        }
    }

    /// Whether this mode treats Mandarin as the language the user is learning
    /// (so explanations/definitions should be richer in Mandarin) vs. English.
    var learningLanguageIsChinese: Bool {
        switch self {
        case .englishToMandarin: return true
        case .mandarinToEnglish: return false
        case .bilingual: return true
        }
    }
}

// MARK: - Photo Scan Language

/// Controls the OCR recognition language for the photo / camera / screenshot
/// pipeline. This is the user-facing fix for "cannot switch languages".
enum PhotoScanLanguage: String, CaseIterable, Identifiable, Codable {
    case auto
    case chinese
    case english
    case bilingual

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .auto: return "自动 · Auto"
        case .chinese: return "中文"
        case .english: return "English"
        case .bilingual: return "双语 · Both"
        }
    }

    var iconName: String {
        switch self {
        case .auto: return "wand.and.stars"
        case .chinese: return "character.textbox"
        case .english: return "textformat.abc"
        case .bilingual: return "globe.asia.australia"
        }
    }

    /// Vision `recognitionLanguages`, ordered by priority. Chinese is listed
    /// first in mixed modes so Chinese glyphs are never mangled into Latin.
    var recognitionLanguages: [String] {
        switch self {
        case .auto, .bilingual: return ["zh-Hans", "zh-Hant", "en-US", "en-GB"]
        case .chinese: return ["zh-Hans", "zh-Hant"]
        case .english: return ["en-US", "en-GB"]
        }
    }

    /// Language correction is an English-language model that corrupts Chinese
    /// OCR output, so it is disabled when recognizing Chinese only.
    var usesLanguageCorrection: Bool {
        switch self {
        case .chinese: return false
        case .auto, .english, .bilingual: return true
        }
    }
}

// MARK: - App Preferences

/// Observable, app-wide preferences singleton (persisted to UserDefaults).
@Observable
@MainActor
final class AppPreferences {

    static let shared = AppPreferences()

    private enum Keys {
        static let learnerMode = "learner_mode"
        static let photoScanLanguage = "photo_scan_language"
        static let dualNarration = "dual_narration"
    }

    /// The app's learner-centric mode. Changing it updates the default
    /// translation direction used across the app.
    var learnerMode: LearnerMode {
        didSet {
            UserDefaults.standard.set(learnerMode.rawValue, forKey: Keys.learnerMode)
            // Adapt the shared default translation direction so all features follow.
            UserDefaults.standard.set(learnerMode.defaultDirection.rawValue, forKey: "defaultDirection")
        }
    }

    /// OCR recognition language preference for the photo pipeline.
    var photoScanLanguage: PhotoScanLanguage {
        didSet {
            UserDefaults.standard.set(photoScanLanguage.rawValue, forKey: Keys.photoScanLanguage)
        }
    }

    /// When enabled, word-detail views offer narration in BOTH languages.
    var dualNarration: Bool {
        didSet {
            UserDefaults.standard.set(dualNarration, forKey: Keys.dualNarration)
        }
    }

    private init() {
        let savedMode = UserDefaults.standard.string(forKey: Keys.learnerMode)
        self.learnerMode = savedMode.flatMap(LearnerMode.init(rawValue:)) ?? .englishToMandarin

        let savedScan = UserDefaults.standard.string(forKey: Keys.photoScanLanguage)
        self.photoScanLanguage = savedScan.flatMap(PhotoScanLanguage.init(rawValue:)) ?? .auto

        // Default ON: dual narration is purely additive and useful for both audiences.
        self.dualNarration = UserDefaults.standard.object(forKey: Keys.dualNarration) as? Bool ?? true
    }
}

//
//  AIModelSettings.swift
//  SwiftMandarin
//
//  Manages AI provider settings and preferences. Supports Apple Intelligence
//  (Foundation Models), local Ollama, and a family of cloud providers
//  (OpenAI, Anthropic/Claude, Deepseek, Doubao, Qwen, Kimi, Zhipu, Minimax)
//  reached over their REST APIs. API keys are stored in the Keychain.
//

import Foundation
import SwiftUI

// MARK: - Provider API Style

/// The request/response convention a cloud provider uses.
enum AIProviderAPIStyle {
    /// OpenAI `/chat/completions` + `/models`, `Authorization: Bearer` auth.
    case openAICompatible
    /// Anthropic `/v1/messages` + `/v1/models`, `x-api-key` + `anthropic-version`.
    case anthropic
}

// MARK: - AI Provider

/// The AI provider to use for AI-powered features.
enum AIProvider: String, CaseIterable, Identifiable, Codable {
    case appleIntelligence = "apple"
    case ollama = "ollama"
    case openAI = "openai"
    case anthropic = "anthropic"
    case deepseek = "deepseek"
    case doubao = "doubao"
    case qwen = "qwen"
    case kimi = "kimi"
    case zhipu = "zhipu"
    case minimax = "minimax"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .appleIntelligence: return "Apple Intelligence"
        case .ollama: return "Ollama (Local)"
        case .openAI: return "OpenAI"
        case .anthropic: return "Claude (Anthropic)"
        case .deepseek: return "DeepSeek"
        case .doubao: return "Doubao 豆包"
        case .qwen: return "Qwen 通义千问"
        case .kimi: return "Kimi 月之暗面"
        case .zhipu: return "Zhipu GLM 智谱"
        case .minimax: return "MiniMax"
        }
    }

    var description: String {
        switch self {
        case .appleIntelligence: return "On-device AI powered by Apple's Foundation Models"
        case .ollama: return "Local AI models running via Ollama server"
        case .openAI: return "GPT models via the OpenAI API"
        case .anthropic: return "Claude models via the Anthropic API"
        case .deepseek: return "DeepSeek chat & reasoning models"
        case .doubao: return "ByteDance Doubao models via Volcengine Ark"
        case .qwen: return "Alibaba Qwen models via DashScope"
        case .kimi: return "Moonshot Kimi models"
        case .zhipu: return "Zhipu GLM models"
        case .minimax: return "MiniMax abab models"
        }
    }

    var iconName: String {
        switch self {
        case .appleIntelligence: return "apple.logo"
        case .ollama: return "server.rack"
        case .openAI: return "sparkles"
        case .anthropic: return "a.circle"
        case .deepseek: return "magnifyingglass.circle"
        case .doubao: return "cloud"
        case .qwen: return "cloud.sun"
        case .kimi: return "moon.stars"
        case .zhipu: return "brain"
        case .minimax: return "bolt.horizontal.circle"
        }
    }

    /// Whether this provider is a remote cloud API requiring an API key.
    var isCloud: Bool {
        switch self {
        case .appleIntelligence, .ollama: return false
        default: return true
        }
    }

    /// Whether this provider can accept image input for vision-based tasks.
    var supportsVision: Bool {
        switch self {
        case .openAI, .anthropic, .doubao, .qwen, .kimi, .zhipu: return true
        case .appleIntelligence, .ollama, .deepseek, .minimax: return false
        }
    }

    // MARK: Cloud REST metadata (only meaningful when `isCloud`)

    var apiStyle: AIProviderAPIStyle {
        switch self {
        case .anthropic: return .anthropic
        default: return .openAICompatible
        }
    }

    /// Default base URL (without a trailing slash). Paths below are appended.
    var defaultBaseURL: String {
        switch self {
        case .openAI: return "https://api.openai.com/v1"
        case .anthropic: return "https://api.anthropic.com"
        case .deepseek: return "https://api.deepseek.com"
        case .doubao: return "https://ark.cn-beijing.volces.com/api/v3"
        case .qwen: return "https://dashscope.aliyuncs.com/compatible-mode/v1"
        case .kimi: return "https://api.moonshot.cn/v1"
        case .zhipu: return "https://open.bigmodel.cn/api/paas/v4"
        case .minimax: return "https://api.minimax.chat/v1"
        case .appleIntelligence, .ollama: return ""
        }
    }

    /// Chat-completion path appended to the base URL.
    var chatPath: String {
        switch self {
        case .anthropic: return "/v1/messages"
        case .minimax: return "/text/chatcompletion_v2"
        default: return "/chat/completions"
        }
    }

    /// Model-list path appended to the base URL, or `nil` when the provider
    /// has no standard listing endpoint (defaults are used instead).
    var modelsPath: String? {
        switch self {
        case .anthropic: return "/v1/models"
        case .openAI, .deepseek, .qwen, .kimi: return "/models"
        case .doubao, .zhipu, .minimax: return nil
        case .appleIntelligence, .ollama: return nil
        }
    }

    /// Curated fallback model IDs shown when live listing is unavailable.
    var defaultModels: [String] {
        switch self {
        case .openAI: return ["gpt-4o", "gpt-4o-mini", "gpt-4.1", "gpt-4.1-mini", "o4-mini"]
        case .anthropic: return ["claude-3-5-sonnet-latest", "claude-3-5-haiku-latest", "claude-3-opus-latest"]
        case .deepseek: return ["deepseek-chat", "deepseek-reasoner"]
        case .doubao: return ["doubao-pro-32k", "doubao-pro-4k", "doubao-lite-32k", "doubao-1.5-vision-pro-32k"]
        case .qwen: return ["qwen-plus", "qwen-turbo", "qwen-max", "qwen-vl-plus", "qwen-vl-max"]
        case .kimi: return ["moonshot-v1-8k", "moonshot-v1-32k", "moonshot-v1-128k", "moonshot-v1-8k-vision-preview"]
        case .zhipu: return ["glm-4-plus", "glm-4-air", "glm-4-flash", "glm-4v-plus", "glm-4v-flash"]
        case .minimax: return ["abab6.5s-chat", "abab6.5g-chat", "MiniMax-Text-01"]
        case .appleIntelligence, .ollama: return []
        }
    }

    /// Keychain account name for this provider's API key.
    var keychainAccount: String { "apikey.\(rawValue)" }

    /// URL to obtain an API key, for the settings help link.
    var apiKeyURL: String? {
        switch self {
        case .openAI: return "https://platform.openai.com/api-keys"
        case .anthropic: return "https://console.anthropic.com/settings/keys"
        case .deepseek: return "https://platform.deepseek.com/api_keys"
        case .doubao: return "https://console.volcengine.com/ark"
        case .qwen: return "https://dashscope.console.aliyun.com/apiKey"
        case .kimi: return "https://platform.moonshot.cn/console/api-keys"
        case .zhipu: return "https://open.bigmodel.cn/usercenter/apikeys"
        case .minimax: return "https://platform.minimaxi.com/user-center/basic-information/interface-key"
        case .appleIntelligence, .ollama: return nil
        }
    }
}

// MARK: - AI Model Settings

/// Observable settings for AI model configuration.
@Observable
@MainActor
final class AIModelSettings {

    static let shared = AIModelSettings()

    // MARK: - UserDefaults Keys

    private enum Keys {
        static let provider = "ai_provider"
        static let ollamaModel = "ollama_model"
        static let ollamaHost = "ollama_host"
        static let enableThinking = "ollama_enable_thinking"
        static let contextLength = "ollama_context_length"
        static let cloudModels = "cloud_model_selections"   // [providerRaw: modelID]
        static let cloudBaseURLs = "cloud_base_overrides"   // [providerRaw: baseURL]
        static let aiPhotoCleanup = "ai_photo_cleanup_enabled"
    }

    // MARK: - Properties

    /// The currently selected AI provider.
    var provider: AIProvider {
        didSet { UserDefaults.standard.set(provider.rawValue, forKey: Keys.provider) }
    }

    /// The selected Ollama model name.
    var ollamaModel: String {
        didSet { UserDefaults.standard.set(ollamaModel, forKey: Keys.ollamaModel) }
    }

    /// The Ollama server host URL.
    var ollamaHost: String {
        didSet {
            UserDefaults.standard.set(ollamaHost, forKey: Keys.ollamaHost)
            updateOllamaServiceHost()
        }
    }

    /// Whether to enable thinking/reasoning mode for Ollama models.
    var enableThinking: Bool {
        didSet { UserDefaults.standard.set(enableThinking, forKey: Keys.enableThinking) }
    }

    /// Context length for Ollama models (in tokens).
    var contextLength: Int {
        didSet { UserDefaults.standard.set(contextLength, forKey: Keys.contextLength) }
    }

    /// When enabled, uploaded photos are passed through the selected AI
    /// provider for OCR cleanup/structuring before downstream processing.
    var aiPhotoCleanupEnabled: Bool {
        didSet { UserDefaults.standard.set(aiPhotoCleanupEnabled, forKey: Keys.aiPhotoCleanup) }
    }

    /// Per-provider selected cloud model IDs.
    private(set) var cloudModelSelections: [String: String] {
        didSet { persistDictionary(cloudModelSelections, key: Keys.cloudModels) }
    }

    /// Per-provider base URL overrides (empty entry → use provider default).
    private(set) var cloudBaseURLOverrides: [String: String] {
        didSet { persistDictionary(cloudBaseURLOverrides, key: Keys.cloudBaseURLs) }
    }

    /// In-memory mirror of Keychain API keys so SwiftUI reacts to changes.
    /// Loaded from the Keychain at init; writes go through to the Keychain.
    private(set) var apiKeys: [String: String] = [:]

    // MARK: - Initialization

    private init() {
        let savedProvider = UserDefaults.standard.string(forKey: Keys.provider) ?? AIProvider.appleIntelligence.rawValue
        self.provider = AIProvider(rawValue: savedProvider) ?? .appleIntelligence

        self.ollamaModel = UserDefaults.standard.string(forKey: Keys.ollamaModel) ?? "gpt-oss:20b"
        self.ollamaHost = UserDefaults.standard.string(forKey: Keys.ollamaHost) ?? "http://localhost:11434"
        self.enableThinking = UserDefaults.standard.object(forKey: Keys.enableThinking) as? Bool ?? true
        self.contextLength = UserDefaults.standard.object(forKey: Keys.contextLength) as? Int ?? 128000
        self.aiPhotoCleanupEnabled = UserDefaults.standard.object(forKey: Keys.aiPhotoCleanup) as? Bool ?? false

        self.cloudModelSelections = AIModelSettings.loadDictionary(key: Keys.cloudModels)
        self.cloudBaseURLOverrides = AIModelSettings.loadDictionary(key: Keys.cloudBaseURLs)

        // Load API keys from Keychain into the observable mirror.
        var keys: [String: String] = [:]
        for p in AIProvider.allCases where p.isCloud {
            if let value = KeychainHelper.get(account: p.keychainAccount), !value.isEmpty {
                keys[p.rawValue] = value
            }
        }
        self.apiKeys = keys

        updateOllamaServiceHost()
    }

    // MARK: - Per-Provider Accessors

    /// The API key for a cloud provider (empty string when none).
    func apiKey(for provider: AIProvider) -> String {
        apiKeys[provider.rawValue] ?? ""
    }

    /// Store or clear a cloud provider's API key (Keychain + observable mirror).
    func setAPIKey(_ value: String, for provider: AIProvider) {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        KeychainHelper.set(trimmed, account: provider.keychainAccount)
        if trimmed.isEmpty {
            apiKeys.removeValue(forKey: provider.rawValue)
        } else {
            apiKeys[provider.rawValue] = trimmed
        }
    }

    /// The effective base URL for a cloud provider (override or default).
    func baseURL(for provider: AIProvider) -> String {
        let override = cloudBaseURLOverrides[provider.rawValue]?.trimmingCharacters(in: .whitespacesAndNewlines)
        if let override, !override.isEmpty { return override }
        return provider.defaultBaseURL
    }

    func setBaseURLOverride(_ value: String, for provider: AIProvider) {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty || trimmed == provider.defaultBaseURL {
            cloudBaseURLOverrides.removeValue(forKey: provider.rawValue)
        } else {
            cloudBaseURLOverrides[provider.rawValue] = trimmed
        }
    }

    /// The selected model for a provider. Ollama maps to `ollamaModel`;
    /// cloud providers use their per-provider selection (or first default).
    func selectedModel(for provider: AIProvider) -> String {
        switch provider {
        case .ollama:
            return ollamaModel
        case .appleIntelligence:
            return ""
        default:
            if let chosen = cloudModelSelections[provider.rawValue], !chosen.isEmpty {
                return chosen
            }
            return provider.defaultModels.first ?? ""
        }
    }

    func setSelectedModel(_ model: String, for provider: AIProvider) {
        switch provider {
        case .ollama:
            ollamaModel = model
        case .appleIntelligence:
            break
        default:
            cloudModelSelections[provider.rawValue] = model
        }
    }

    // MARK: - Availability

    /// Whether Apple Intelligence is available.
    var isAppleIntelligenceAvailable: Bool {
        #if canImport(FoundationModels)
        return AIWordExplanationService.shared.isAvailable
        #else
        return false
        #endif
    }

    /// Whether a given provider is usable right now.
    func isAvailable(_ provider: AIProvider) -> Bool {
        switch provider {
        case .appleIntelligence:
            return isAppleIntelligenceAvailable
        case .ollama:
            return OllamaService.shared.isConnected
        default:
            return !apiKey(for: provider).isEmpty
        }
    }

    /// Whether any provider is available for AI features.
    var isAnyProviderAvailable: Bool {
        AIProvider.allCases.contains { isAvailable($0) }
    }

    /// Current effective provider — the selected one if usable, otherwise the
    /// first available provider, otherwise the selected one (so errors surface).
    var effectiveProvider: AIProvider {
        if isAvailable(provider) { return provider }
        return AIProvider.allCases.first { isAvailable($0) } ?? provider
    }

    /// Whether Ollama is selected and available.
    var isOllamaActive: Bool {
        provider == .ollama && OllamaService.shared.isConnected
    }

    /// Status message for the current configuration.
    var statusMessage: String {
        switch provider {
        case .appleIntelligence:
            return isAppleIntelligenceAvailable
                ? "Apple Intelligence is ready"
                : (AIWordExplanationService.shared.unavailabilityReason ?? "Apple Intelligence is not available")
        case .ollama:
            if OllamaService.shared.isConnected {
                return ollamaModel.isEmpty ? "Connected — select a model" : "Connected to \(ollamaModel)"
            }
            return OllamaService.shared.connectionError ?? "Not connected to Ollama"
        default:
            if apiKey(for: provider).isEmpty {
                return "Add your \(provider.displayName) API key"
            }
            let model = selectedModel(for: provider)
            return model.isEmpty ? "Ready — select a model" : "Using \(model)"
        }
    }

    /// Options dictionary for Ollama requests based on current settings.
    var ollamaOptions: [String: Ollama.Value] {
        [
            "num_ctx": .int(contextLength),
            "temperature": .double(0.7),
            "top_p": .double(0.9),
            "repeat_penalty": .double(1.1),
            "num_predict": .int(-1),
        ]
    }

    // MARK: - Methods

    private func updateOllamaServiceHost() {
        if let url = URL(string: ollamaHost) {
            OllamaService.shared.hostURL = url
        }
    }

    /// Refresh connection and available models for the active provider.
    func refreshConnection() async {
        switch provider {
        case .ollama:
            await OllamaService.shared.checkConnection()
            if OllamaService.shared.isConnected {
                await OllamaService.shared.refreshModels()
            }
        default:
            if provider.isCloud {
                await CloudAIService.shared.refreshModels(for: provider)
            }
        }
    }

    /// Select the first available Ollama model if none is selected.
    func selectDefaultModelIfNeeded() {
        if ollamaModel.isEmpty, let firstModel = OllamaService.shared.availableModels.first {
            ollamaModel = firstModel.name
        }
    }

    /// Reset to default settings.
    func resetToDefaults() {
        provider = .appleIntelligence
        ollamaModel = "gpt-oss:20b"
        ollamaHost = "http://localhost:11434"
        enableThinking = true
        contextLength = 128000
        aiPhotoCleanupEnabled = false
    }

    // MARK: - Persistence Helpers

    private func persistDictionary(_ dict: [String: String], key: String) {
        if let data = try? JSONEncoder().encode(dict) {
            UserDefaults.standard.set(data, forKey: key)
        }
    }

    private static func loadDictionary(key: String) -> [String: String] {
        guard let data = UserDefaults.standard.data(forKey: key),
              let dict = try? JSONDecoder().decode([String: String].self, from: data) else {
            return [:]
        }
        return dict
    }
}

// MARK: - Ollama Import

import Ollama

//
//  CloudAIService.swift
//  SwiftMandarin
//
//  URLSession-based client for cloud AI providers. Supports the OpenAI
//  chat-completions convention (OpenAI, DeepSeek, Doubao, Qwen/DashScope,
//  Kimi/Moonshot, Zhipu, MiniMax) and the Anthropic Messages convention
//  (Claude). Provides model listing, text chat, vision chat, and translation.
//
//  No third-party dependency — built directly on Foundation so any
//  OpenAI-compatible endpoint can be reached by configuring base URL + key.
//

import Foundation
import SwiftUI

// MARK: - Model Info

/// A provider-neutral model descriptor for the settings model picker.
struct CloudModelInfo: Identifiable, Hashable, Codable {
    let id: String
    var displayName: String { id }
}

// MARK: - Errors

enum CloudAIError: LocalizedError {
    case notCloudProvider
    case missingAPIKey(String)
    case invalidURL
    case requestEncodingFailed
    case httpError(Int, String)
    case emptyResponse
    case unexpectedResponse(String)

    var errorDescription: String? {
        switch self {
        case .notCloudProvider:
            return "Selected provider is not a cloud provider."
        case .missingAPIKey(let name):
            return "No API key configured for \(name). Add it in Settings → AI."
        case .invalidURL:
            return "The provider base URL is invalid."
        case .requestEncodingFailed:
            return "Failed to encode the request."
        case .httpError(let code, let body):
            let trimmed = body.count > 300 ? String(body.prefix(300)) + "…" : body
            return "Provider returned HTTP \(code): \(trimmed)"
        case .emptyResponse:
            return "The provider returned an empty response."
        case .unexpectedResponse(let detail):
            return "Unexpected response from provider: \(detail)"
        }
    }
}

// MARK: - Cloud AI Service

@Observable
@MainActor
final class CloudAIService {

    static let shared = CloudAIService()

    /// Per-provider live model lists (keyed by `AIProvider.rawValue`).
    private(set) var availableModels: [String: [CloudModelInfo]] = [:]

    /// Providers currently fetching their model list.
    private(set) var loadingProviders: Set<String> = []

    /// Last error message per provider (keyed by `AIProvider.rawValue`).
    private(set) var lastError: [String: String] = [:]

    private let session: URLSession = {
        let config = URLSessionConfiguration.default
        config.timeoutIntervalForRequest = 60
        config.timeoutIntervalForResource = 120
        config.waitsForConnectivity = true
        return URLSession(configuration: config)
    }()

    private init() {}

    // MARK: - Public State Accessors

    /// Models to show for a provider: live list if available, else curated defaults.
    func models(for provider: AIProvider) -> [CloudModelInfo] {
        if let live = availableModels[provider.rawValue], !live.isEmpty {
            return live
        }
        return provider.defaultModels.map { CloudModelInfo(id: $0) }
    }

    func isLoading(_ provider: AIProvider) -> Bool {
        loadingProviders.contains(provider.rawValue)
    }

    func error(for provider: AIProvider) -> String? {
        lastError[provider.rawValue]
    }

    // MARK: - Model Listing

    /// Fetch the available model list for a cloud provider via its API.
    /// Falls back to curated defaults when no listing endpoint exists or the
    /// request fails; never throws (errors are stored in `lastError`).
    func refreshModels(for provider: AIProvider) async {
        guard provider.isCloud else { return }
        let settings = AIModelSettings.shared
        let key = settings.apiKey(for: provider)

        lastError[provider.rawValue] = nil

        guard !key.isEmpty else {
            lastError[provider.rawValue] = CloudAIError.missingAPIKey(provider.displayName).localizedDescription
            return
        }

        // Providers without a standard listing endpoint use curated defaults.
        guard let modelsPath = provider.modelsPath else {
            availableModels[provider.rawValue] = provider.defaultModels.map { CloudModelInfo(id: $0) }
            return
        }

        guard let url = URL(string: settings.baseURL(for: provider) + modelsPath) else {
            lastError[provider.rawValue] = CloudAIError.invalidURL.localizedDescription
            return
        }

        loadingProviders.insert(provider.rawValue)
        defer { loadingProviders.remove(provider.rawValue) }

        var request = URLRequest(url: url)
        request.httpMethod = "GET"
        applyAuthHeaders(&request, provider: provider, key: key)

        do {
            let (data, response) = try await session.data(for: request)
            guard let http = response as? HTTPURLResponse else {
                throw CloudAIError.unexpectedResponse("No HTTP response")
            }
            guard (200...299).contains(http.statusCode) else {
                throw CloudAIError.httpError(http.statusCode, String(data: data, encoding: .utf8) ?? "")
            }
            let ids = Self.parseModelIDs(from: data)
            if ids.isEmpty {
                // Keep defaults visible if the endpoint returned nothing useful.
                availableModels[provider.rawValue] = provider.defaultModels.map { CloudModelInfo(id: $0) }
            } else {
                availableModels[provider.rawValue] = ids.map { CloudModelInfo(id: $0) }
            }
        } catch {
            lastError[provider.rawValue] = error.localizedDescription
            // Surface curated defaults so the picker remains usable.
            if availableModels[provider.rawValue] == nil {
                availableModels[provider.rawValue] = provider.defaultModels.map { CloudModelInfo(id: $0) }
            }
        }
    }

    /// Parse model IDs from common listing-response shapes.
    private static func parseModelIDs(from data: Data) -> [String] {
        guard let json = try? JSONSerialization.jsonObject(with: data) else { return [] }
        let container: [Any]?
        if let dict = json as? [String: Any] {
            container = (dict["data"] as? [Any]) ?? (dict["models"] as? [Any])
        } else {
            container = json as? [Any]
        }
        guard let items = container else { return [] }
        var ids: [String] = []
        for item in items {
            if let s = item as? String {
                ids.append(s)
            } else if let obj = item as? [String: Any] {
                if let id = obj["id"] as? String { ids.append(id) }
                else if let name = obj["name"] as? String { ids.append(name) }
            }
        }
        return ids.sorted()
    }

    // MARK: - Chat

    /// Send a chat request and return the assistant's text content.
    /// - Parameters:
    ///   - imageData: optional image for vision-capable providers/models.
    ///   - jsonMode: request a JSON object response where supported.
    func chat(
        provider: AIProvider,
        model: String,
        system: String,
        user: String,
        imageData: Data? = nil,
        jsonMode: Bool = false,
        maxTokens: Int = 4096
    ) async throws -> String {
        guard provider.isCloud else { throw CloudAIError.notCloudProvider }
        let settings = AIModelSettings.shared
        let key = settings.apiKey(for: provider)
        guard !key.isEmpty else { throw CloudAIError.missingAPIKey(provider.displayName) }

        let base = settings.baseURL(for: provider)
        guard let url = URL(string: base + provider.chatPath) else { throw CloudAIError.invalidURL }

        let useImage = imageData != nil && provider.supportsVision

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        applyAuthHeaders(&request, provider: provider, key: key)

        let body: [String: Any]
        switch provider.apiStyle {
        case .openAICompatible:
            body = Self.openAIBody(
                model: model, system: system, user: user,
                imageData: useImage ? imageData : nil, jsonMode: jsonMode, maxTokens: maxTokens
            )
        case .anthropic:
            body = Self.anthropicBody(
                model: model, system: system, user: user,
                imageData: useImage ? imageData : nil, maxTokens: maxTokens
            )
        }

        guard let httpBody = try? JSONSerialization.data(withJSONObject: body) else {
            throw CloudAIError.requestEncodingFailed
        }
        request.httpBody = httpBody

        let (data, response) = try await session.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw CloudAIError.unexpectedResponse("No HTTP response")
        }
        guard (200...299).contains(http.statusCode) else {
            throw CloudAIError.httpError(http.statusCode, String(data: data, encoding: .utf8) ?? "")
        }

        let content: String?
        switch provider.apiStyle {
        case .openAICompatible: content = Self.parseOpenAIContent(from: data)
        case .anthropic: content = Self.parseAnthropicContent(from: data)
        }

        guard let text = content, !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw CloudAIError.emptyResponse
        }
        return text
    }

    /// Translate text using a cloud provider.
    func translate(_ text: String, sourceIsChinese: Bool, provider: AIProvider, model: String) async throws -> String {
        let system = """
        You are an expert translator between English and Mandarin Chinese (Simplified).
        Translate accurately and naturally, preserving meaning, tone and register.
        For English→Chinese use 简体中文. Respond with ONLY the translation, no commentary.
        """
        let direction = sourceIsChinese ? "Chinese to English" : "English to Chinese"
        let user = "Translate the following from \(direction):\n\n\(text)"
        let result = try await chat(provider: provider, model: model, system: system, user: user, maxTokens: 2048)
        return result.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    // MARK: - Request Building

    private func applyAuthHeaders(_ request: inout URLRequest, provider: AIProvider, key: String) {
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        switch provider.apiStyle {
        case .openAICompatible:
            request.setValue("Bearer \(key)", forHTTPHeaderField: "Authorization")
        case .anthropic:
            request.setValue(key, forHTTPHeaderField: "x-api-key")
            request.setValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
        }
    }

    private static func openAIBody(
        model: String, system: String, user: String,
        imageData: Data?, jsonMode: Bool, maxTokens: Int
    ) -> [String: Any] {
        var systemPrompt = system
        var userContent: Any = user

        if jsonMode, !systemPrompt.lowercased().contains("json") {
            systemPrompt += "\n\nRespond with a single valid JSON object."
        }

        if let imageData {
            let dataURL = "data:\(mediaType(for: imageData));base64,\(imageData.base64EncodedString())"
            userContent = [
                ["type": "text", "text": user],
                ["type": "image_url", "image_url": ["url": dataURL]],
            ]
        }

        var body: [String: Any] = [
            "model": model,
            "messages": [
                ["role": "system", "content": systemPrompt],
                ["role": "user", "content": userContent],
            ],
            "temperature": 0.3,
            "stream": false,
            "max_tokens": maxTokens,
        ]
        if jsonMode {
            body["response_format"] = ["type": "json_object"]
        }
        return body
    }

    private static func anthropicBody(
        model: String, system: String, user: String,
        imageData: Data?, maxTokens: Int
    ) -> [String: Any] {
        var userContent: [[String: Any]] = [["type": "text", "text": user]]
        if let imageData {
            userContent.append([
                "type": "image",
                "source": [
                    "type": "base64",
                    "media_type": mediaType(for: imageData),
                    "data": imageData.base64EncodedString(),
                ],
            ])
        }
        return [
            "model": model,
            "max_tokens": maxTokens,
            "system": system,
            "messages": [["role": "user", "content": userContent]],
        ]
    }

    // MARK: - Response Parsing

    private static func parseOpenAIContent(from data: Data) -> String? {
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
        guard let choices = json["choices"] as? [[String: Any]], let first = choices.first else { return nil }
        if let message = first["message"] as? [String: Any] {
            // content may be a string or an array of content parts.
            if let content = message["content"] as? String { return content }
            if let parts = message["content"] as? [[String: Any]] {
                return parts.compactMap { $0["text"] as? String }.joined()
            }
        }
        if let text = first["text"] as? String { return text }
        return nil
    }

    private static func parseAnthropicContent(from data: Data) -> String? {
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
        guard let content = json["content"] as? [[String: Any]] else { return nil }
        let texts = content.compactMap { block -> String? in
            (block["type"] as? String) == "text" ? block["text"] as? String : nil
        }
        return texts.isEmpty ? nil : texts.joined()
    }

    // MARK: - Media Type Detection

    private static func mediaType(for data: Data) -> String {
        guard let first = data.first else { return "image/jpeg" }
        switch first {
        case 0x89: return "image/png"
        case 0xFF: return "image/jpeg"
        case 0x47: return "image/gif"
        case 0x52: return "image/webp"
        default: return "image/jpeg"
        }
    }
}

