cat > /tmp/verify_ocr_logic.swift << 'SWIFT'
// Standalone replica of the shipped detection + cleaning logic to validate
// the concern-A fix deterministically.

extension Unicode.Scalar {
    var isCJKIdeograph: Bool {
        (0x4E00...0x9FFF).contains(value) || (0x3400...0x4DBF).contains(value) ||
        (0xF900...0xFAFF).contains(value) || (0x20000...0x2A6DF).contains(value) ||
        (0x2A700...0x2EBEF).contains(value)
    }
}
extension Character { var isChineseCharacter: Bool { unicodeScalars.first?.isCJKIdeograph ?? false } }

enum Lang: Equatable { case chinese, english, other }

func detectRobust(_ text: String) -> Lang {
    var cjk = 0, latin = 0
    for s in text.unicodeScalars {
        if s.isCJKIdeograph { cjk += 1 }
        else if (0x41...0x5A).contains(s.value) || (0x61...0x7A).contains(s.value) { latin += 1 }
    }
    if cjk == 0 && latin == 0 { return .other }
    if cjk > 0 && cjk * 3 >= latin { return .chinese }
    if latin > cjk * 3 { return .english }
    return .other
}

func removeWhitespaceBetweenCJK(_ s: String) -> String {
    let chars = Array(s); var out: [Character] = []; var i = 0
    while i < chars.count {
        let c = chars[i]
        if c == " " || c == "\t" || c == "\n" || c == "\r" {
            var j = i
            while j < chars.count, chars[j] == " " || chars[j] == "\t" || chars[j] == "\n" || chars[j] == "\r" { j += 1 }
            let prev = out.last; let next = j < chars.count ? chars[j] : nil
            if let p = prev, let n = next, p.isChineseCharacter, n.isChineseCharacter { } else { out.append(" ") }
            i = j
        } else { out.append(c); i += 1 }
    }
    return String(out)
}
func cleanChinese(_ blocks: [String]) -> String {
    let joined = blocks.joined(separator: "\n")
    let despaced = removeWhitespaceBetweenCJK(joined)
    return despaced.replacingOccurrences(of: "[ \\t\\n]+", with: " ", options: .regularExpression)
        .trimmingCharacters(in: .whitespacesAndNewlines)
}

var pass = 0, fail = 0
func check(_ name: String, _ got: Any, _ want: Any) {
    if "\(got)" == "\(want)" { pass += 1; print("✅ \(name): \(got)") }
    else { fail += 1; print("❌ \(name): got \(got), want \(want)") }
}

// Detection: the bug was Chinese mis-detected as English.
check("pure Chinese", detectRobust("你好世界，我是一名学生。"), Lang.chinese)
check("pure English", detectRobust("Hello world, this is an English sentence."), Lang.english)
check("Chinese-dominant mixed", detectRobust("我喜欢学习 English 和数学"), Lang.chinese)
check("English-dominant mixed", detectRobust("The word for cat is 猫 in Chinese"), Lang.english)
check("Chinese textbook line", detectRobust("第一课 你好"), Lang.chinese)
check("traditional Chinese", detectRobust("學習中文很有趣"), Lang.chinese)

// Cleaning: Chinese OCR with spurious spaces/newlines between Han chars.
