                .padding()
            }
            .navigationTitle("作业批改 · Grading")
            #if os(iOS)
            .navigationBarTitleDisplayMode(.inline)
            #endif
            .toolbar {
                ToolbarItem(placement: .confirmationAction) {
                    Button("完成") { dismiss() }
                }
            }
            .onChange(of: workbookItems) { _, items in
                Task { await loadImages(items, into: \.workbookImages, loading: \.isLoadingWorkbook) }
            }
            .onChange(of: answerItems) { _, items in
                Task { await loadImages(items, into: \.answerImages, loading: \.isLoadingAnswers) }
            }
        }
    }

    // MARK: - Sections

    @ViewBuilder
