    private func uploadSection(
        title: String,
        systemImage: String,
        items: Binding<[PhotosPickerItem]>,
        images: [Data],
        isLoading: Bool,
        onClear: @escaping () -> Void
    ) -> some View {
        VStack(alignment: .leading, spacing: 12) {
