    private func assign(_ keyPath: ReferenceWritableKeyPath<WorkbookGradingView, [Data]>, _ value: [Data]) {
        if keyPath == \WorkbookGradingView.workbookImages { workbookImages = value }
        else if keyPath == \WorkbookGradingView.answerImages { answerImages = value }
    }

    private func setLoading(_ keyPath: ReferenceWritableKeyPath<WorkbookGradingView, Bool>, _ value: Bool) {
        if keyPath == \WorkbookGradingView.isLoadingWorkbook { isLoadingWorkbook = value }
        else if keyPath == \WorkbookGradingView.isLoadingAnswers { isLoadingAnswers = value }
    }
