import Foundation

func extractJSONObject(from text: String) -> Data? {
    guard let s = text.firstIndex(of: "{"), let e = text.lastIndex(of: "}"), s < e else { return nil }
    return String(text[s...e]).data(using: .utf8)
}
struct Vocab: Decodable { let term: String; let reading: String; let meaning: String
    init(from d: Decoder) throws { let c = try d.container(keyedBy: CodingKeys.self)
        term = try c.decode(String.self, forKey: .term)
        reading = (try? c.decode(String.self, forKey: .reading)) ?? ""
        meaning = (try? c.decode(String.self, forKey: .meaning)) ?? "" }
    enum CodingKeys: String, CodingKey { case term, reading, meaning } }
struct Q: Decodable { let questionNumber, question, studentAnswer, correctAnswer, explanation: String; let isCorrect: Bool; let vocab: Vocab?
    enum CodingKeys: String, CodingKey { case questionNumber, question, studentAnswer, correctAnswer, isCorrect, explanation, vocab }
    init(from d: Decoder) throws { let c = try d.container(keyedBy: CodingKeys.self)
        questionNumber = (try? c.decode(String.self, forKey: .questionNumber)) ?? ""
        question = (try? c.decode(String.self, forKey: .question)) ?? ""
        studentAnswer = (try? c.decode(String.self, forKey: .studentAnswer)) ?? ""
        correctAnswer = (try? c.decode(String.self, forKey: .correctAnswer)) ?? ""
        isCorrect = (try? c.decode(Bool.self, forKey: .isCorrect)) ?? false
        explanation = (try? c.decode(String.self, forKey: .explanation)) ?? ""
        vocab = try? c.decode(Vocab.self, forKey: .vocab) } }
struct Result: Decodable { let score, summary: String; let questions: [Q]
    enum CodingKeys: String, CodingKey { case score, summary, questions }
    init(from d: Decoder) throws { let c = try d.container(keyedBy: CodingKeys.self)
        score = (try? c.decode(String.self, forKey: .score)) ?? ""
        summary = (try? c.decode(String.self, forKey: .summary)) ?? ""
        questions = (try? c.decode([Q].self, forKey: .questions)) ?? [] }
    var correct: Int { questions.filter { $0.isCorrect }.count }
    var wrongWithVocab: Int { questions.filter { !$0.isCorrect && $0.vocab != nil }.count } }

func decode(_ s: String) -> Result? { extractJSONObject(from: s).flatMap { try? JSONDecoder().decode(Result.self, from: $0) } }

var pass = 0, fail = 0
func chk(_ n: String, _ c: Bool) { if c { pass += 1; print("✅ \(n)") } else { fail += 1; print("❌ \(n)") } }

